from functools import wraps
from typing import Tuple, Type, Any, Callable, Optional, Union

def retry(
    func: Callable[[], Any],
    max_attempts: int = 3,
    delay: float = 1.0,
    exceptions: Tuple[Type[Exception], ...] = (ValueError, TimeoutError, IOError)
) -> Callable[[], Any]:
    """
    Decorador para reintentar la ejecución de una función hasta que se logre éxito o se agoten los intentos.

    Parámetros:
        func: La función a decorar.
        max_attempts: Número máximo de intentos (incluyendo el último).
        delay: Tiempo en segundos entre cada intento fallido.
        exceptions: Tupla de tipos de excepciones que causa el reintentamiento.

    Retorna:
        La función decorada.
    """

    def decorator():
        @wraps(func)
        def wrapper(*args, **kwargs):
            last_exception: Optional[Type[Exception]] = None

            for attempt in range(1, max_attempts + 1):
                try:
                    return func(*args, **kwargs)
                except exceptions as e:
                    # Si se agotan los intentos, relanza la última excepción
                    if attempt == max_attempts:
                        last_exception = e.__class__
                    else:
                        # Retraso antes de intentar de nuevo
                        import time
                        time.sleep(delay)
                    continue
                except Exception:
                    # Si ocurre otra excepción no especificada, no reintentamos
                    raise

            # Si llegamos aquí, significa que se agotaron los intentos
            if last_exception:
                raise last_exception
            raise

        return wrapper

    return decorator
```

### Uso:

```python
import time
from functools import wraps

def fetch_data(url):
    """
    Ejemplo de función que podría fallar por timeouts o errores de red.
    """
    try:
        response = requests.get(url)
        return response.json()
    except requests.exceptions.Timeout:
        raise
    except requests.exceptions.ConnectionError:
        raise
    except Exception:
        raise

# Decorador
@retry(max_attempts=3, delay=1.0, exceptions=(IOError, TimeoutError))
def fetch_data_retry(url):
    return fetch_data(url)

# Ejemplo de uso
try:
    result = fetch_data_retry("https://example.com")
    print(result)
except Exception as e:
    print(f"Error: {e}")
```

### Notas:

- Si la función tiene éxito, devuelve su resultado normal.
- Si se agotan los intentos, relanza la última excepción capturada.
- Las excepciones no especificadas en `exceptions` no causan reintentos.

